//#region src/core/constants/task-status.ts
/**
* Unified task status definitions
*
* Status hierarchy:
* - TASK_*:     Single-task level status
* - WORKFLOW_*: Workflow level status
* - NODE_*:     Node level status (workflow only)
*
* Status lifecycle:
* PENDING -> RUNNING -> COMPLETED/FAILED/CANCELLED
*/
/**
* General task status (single-task and workflow level)
*/
const TaskStatus = {
	PENDING: "PENDING",
	RUNNING: "RUNNING",
	COMPLETED: "COMPLETED",
	FAILED: "FAILED",
	CANCELLED: "CANCELLED"
};
/**
* Workflow level status
*/
const WorkflowStatus = {
	WORKFLOW_STARTED: "WORKFLOW_STARTED",
	WORKFLOW_COMPLETED: "WORKFLOW_COMPLETED",
	WORKFLOW_FAILED: "WORKFLOW_FAILED",
	WORKFLOW_CANCELLED: "WORKFLOW_CANCELLED"
};
/**
* Node level status
*/
const NodeStatus = {
	NODE_STARTED: "NODE_STARTED",
	NODE_RUNNING: "NODE_RUNNING",
	NODE_COMPLETED: "NODE_COMPLETED",
	NODE_FAILED: "NODE_FAILED"
};
/**
* Set of terminal statuses
*/
const TERMINAL_STATUSES = /* @__PURE__ */ new Set([
	TaskStatus.COMPLETED,
	TaskStatus.FAILED,
	TaskStatus.CANCELLED,
	WorkflowStatus.WORKFLOW_COMPLETED,
	WorkflowStatus.WORKFLOW_FAILED,
	WorkflowStatus.WORKFLOW_CANCELLED
]);
TaskStatus.RUNNING, NodeStatus.NODE_STARTED, NodeStatus.NODE_RUNNING;
/**
* Check whether the status is a terminal status
*/
function isTerminalStatus(status) {
	return TERMINAL_STATUSES.has(status);
}
/**
* Map SSE status to internal task status
* Used in use-task.ts and other front-end state management
*/
function mapSSEStatusToTaskStatus(sseStatus) {
	switch (sseStatus) {
		case TaskStatus.PENDING: return "PENDING";
		case TaskStatus.RUNNING:
		case NodeStatus.NODE_STARTED:
		case NodeStatus.NODE_RUNNING: return "PROCESSING";
		case TaskStatus.COMPLETED:
		case WorkflowStatus.WORKFLOW_COMPLETED:
		case NodeStatus.NODE_COMPLETED: return "COMPLETED";
		case TaskStatus.CANCELLED:
		case WorkflowStatus.WORKFLOW_CANCELLED: return "CANCELLED";
		case TaskStatus.FAILED:
		case WorkflowStatus.WORKFLOW_FAILED:
		case NodeStatus.NODE_FAILED: return "FAILED";
		default: return "PENDING";
	}
}
