/**
* Hook for managing multiple states of a node
* @param initialState Initial state object
* @param nodeData Node's data object
* @returns [state, updateState] Similar to useState interface, but supports object updates
*/
function useNodeState(initialState, nodeData) {
	const id = useNodeId();
	const flowUpdates = useFlow((s) => s.updates);
	const [state, setState] = useState(() => ({
		...initialState,
		...nodeData
	}));
	const stateRef = useRef(state);
	stateRef.current = state;
	useEffect(() => {
		setState((prev) => ({
			...prev,
			...nodeData
		}));
	}, [nodeData]);
	return [state, useCallback((updates) => {
		const prev = stateRef.current;
		const newState = typeof updates === "function" ? updates(prev) : {
			...prev,
			...updates
		};
		stateRef.current = newState;
		setState(newState);
		if (id) flowUpdates(id, newState);
	}, [id, flowUpdates])];
}
